def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(val, default=(0, 0)):
        if isinstance(val, (list, tuple)) and len(val) >= 2:
            try:
                return int(val[0]), int(val[1])
            except:
                return default
        return default

    def step_toward(a, b):
        ax, ay = a
        bx, by = b
        return [clamp_step(bx - ax), clamp_step(by - ay)]

    def step_away(a, b):
        ax, ay = a
        bx, by = b
        return [clamp_step(ax - bx), clamp_step(ay - by)]

    def nearest(points, origin):
        best = None
        best_d = None
        ox, oy = origin
        for p in points or []:
            if isinstance(p, (list, tuple)) and len(p) >= 2:
                try:
                    x, y = int(p[0]), int(p[1])
                except:
                    continue
                d = abs(x - ox) + abs(y - oy)
                if best is None or d < best_d:
                    best = (x, y)
                    best_d = d
        return best

    env = (observation or {}).get("environment_name", "resource_collection")
    sx, sy = pos((observation or {}).get("self_position"), (0, 0))
    ox, oy = pos((observation or {}).get("opponent_position"), (sx, sy))
    w = (observation or {}).get("grid_width", 0)
    h = (observation or {}).get("grid_height", 0)

    if env == "pursuit_evasion":
        role = (observation or {}).get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward((sx, sy), (ox, oy))
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = None
        best_d = None
        for c in corners:
            d = abs(c[0] - ox) + abs(c[1] - oy)
            if target is None or d > best_d:
                target = c
                best_d = d
        return step_toward((sx, sy), target or (sx, sy))

    if env == "territory_control":
        targets = (observation or {}).get("unclaimed_cells") or (observation or {}).get("opponent_territory") or []
        target = nearest(targets, (sx, sy))
        if target is None:
            cx = (w - 1) // 2 if w else sx
            cy = (h - 1) // 2 if h else sy
            return step_toward((sx, sy), (cx, cy))
        return step_toward((sx, sy), target)

    resources = (observation or {}).get("resources") or (observation or {}).get("resource_positions") or []
    target = nearest(resources, (sx, sy))
    if target is not None:
        return step_toward((sx, sy), target)

    # Fallbacks: move away from opponent, else toward center if known.
    if ox != sx or oy != sy:
        return step_away((sx, sy), (ox, oy))
    cx = (w - 1) // 2 if w else sx
    cy = (h - 1) // 2 if h else sy
    return step_toward((sx, sy), (cx, cy))

